use super::*;
use std::{fs,path::PathBuf,time::Duration};
struct Qa{root:PathBuf,service:Arc<ImportService>,owner:Owner}
impl Qa{fn new()->Self{let root=std::env::temp_dir().join("opencode").join(format!("5b7-5d3b2-unit-{}",uuid::Uuid::new_v4()));fs::create_dir(&root).unwrap();let service=Arc::new(ImportService::new(Repository::new(root.clone(),Policy::import_qa()),true));let owner=service.owner("main",123).unwrap();Self{root,service,owner}}
fn prepare(&self,kind:Kind,name:&str)->State{let s=self.service.begin(&self.owner,kind).unwrap();self.service.selector_closed();self.service.selected(&self.owner,&s.session_id,vec![fixture(name)]).unwrap();self.service.get(&self.owner,&s.session_id).unwrap()}
fn trust(&self){let s=self.prepare(Kind::Trust,"trust.json");assert_eq!(self.service.confirm(&self.owner,&s.session_id,s.preview_nonce.as_ref().unwrap()).unwrap().phase,"committed");}}
impl Drop for Qa{fn drop(&mut self){let _=fs::remove_dir_all(&self.root);}}
fn fixture(name:&str)->Vec<u8>{fs::read(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b2/fixtures").join(name)).unwrap()}
fn reject<T>(r:Result<T>,code:&str){match r{Err(e)=>assert_eq!(e.code,code),Ok(_)=>panic!("Expected {code}")}}
#[test]fn constructor_and_configuration_do_not_create_fiscal_storage(){let q=Qa::new();assert!(!q.root.join("fiscal").exists());assert!(q.service.enabled().is_ok());}
#[test]fn trust_preview_first_use_does_not_initialize(){let q=Qa::new();let s=q.prepare(Kind::Trust,"trust.json");assert_eq!(s.phase,"ready");assert!(s.summary.unwrap().repository_id.is_none());assert!(!q.root.join("fiscal").exists());}
#[test]fn complete_trust_package_flow_preserves_bytes_and_is_not_executable(){let q=Qa::new();q.trust();let s=q.prepare(Kind::Package,"package1.nomina-fiscal");assert_eq!(q.service.repository.open_existing().unwrap().generation,1);let nonce=s.preview_nonce.unwrap();let done=q.service.confirm(&q.owner,&s.session_id,&nonce).unwrap();assert_eq!(done.phase,"committed");assert_eq!(done.receipt.unwrap().execution,"not-authorized-for-execution");let hash=nomina_fiscal_package::hashes::sha256(&fixture("package1.nomina-fiscal"));assert_eq!(q.service.repository.read_original(&hash).unwrap(),fixture("package1.nomina-fiscal"));assert_eq!(q.service.repository.installation_metadata(20,"").unwrap().1.len(),1);}
#[test]fn duplicate_confirmation_and_lost_response_reuse_operation(){let q=Qa::new();q.trust();let s=q.prepare(Kind::Package,"package1.nomina-fiscal");let a=q.service.confirm(&q.owner,&s.session_id,s.preview_nonce.as_ref().unwrap()).unwrap();let b=q.service.confirm(&q.owner,&s.session_id,s.preview_nonce.as_ref().unwrap()).unwrap();assert_eq!(a.receipt,b.receipt);assert_eq!(q.service.repository.open_existing().unwrap().generation,2);assert!(q.service.repository.operation_status(&s.operation_id).unwrap().is_some());}
#[test]fn callback_after_cancel_cannot_resurrect(){let q=Qa::new();let s=q.service.begin(&q.owner,Kind::Trust).unwrap();q.service.cancel(&q.owner,&s.session_id).unwrap();q.service.selector_closed();reject(q.service.selected(&q.owner,&s.session_id,vec![fixture("trust.json")]),"SESSION_CANCELLED");assert_eq!(q.service.get(&q.owner,&s.session_id).unwrap().phase,"cancelled");assert!(!q.root.join("fiscal").exists());}
#[test]fn native_document_epoch_invalidates_old_tokens(){let q=Qa::new();let s=q.prepare(Kind::Trust,"trust.json");q.service.navigation("main",true);reject(q.service.owner("main",123),"DOCUMENT_NOT_READY");q.service.navigation("main",false);let other=q.service.owner("main",123).unwrap();assert_ne!(q.owner,other);reject(q.service.confirm(&other,&s.session_id,s.preview_nonce.as_ref().unwrap()),"SESSION_OWNER_MISMATCH");}
#[test]fn wrong_window_handle_and_nonce_are_not_js_authority(){let q=Qa::new();reject(q.service.owner("other",123),"UNAUTHORIZED_WINDOW");reject(q.service.owner("main",0),"UNAUTHORIZED_WINDOW");let s=q.prepare(Kind::Trust,"trust.json");reject(q.service.confirm(&q.owner,&s.session_id,&uuid::Uuid::new_v4().to_string()),"PREVIEW_NONCE_MISMATCH");assert!(!q.root.join("fiscal").exists());}
#[test]fn ttl_absolute_and_idle_exact_boundary(){for (absolute,idle) in [(600,0),(0,300)]{let q=Qa::new();let s=q.prepare(Kind::Trust,"trust.json");q.service.age(&s.session_id,Duration::from_secs(absolute),Duration::from_secs(idle));assert_eq!(q.service.get(&q.owner,&s.session_id).unwrap().phase,"expired");reject(q.service.confirm(&q.owner,&s.session_id,s.preview_nonce.as_ref().unwrap()),"SESSION_EXPIRED");}let q=Qa::new();let s=q.prepare(Kind::Trust,"trust.json");q.service.age(&s.session_id,Duration::from_secs(598),Duration::from_secs(298));assert_eq!(q.service.get(&q.owner,&s.session_id).unwrap().phase,"ready");}
#[test]fn bounded_session_and_dialog_capacity(){let q=Qa::new();let a=q.service.begin(&q.owner,Kind::Trust).unwrap();reject(q.service.begin(&q.owner,Kind::Trust),"SELECTOR_BUSY");q.service.selector_closed();q.service.selected(&q.owner,&a.session_id,vec![fixture("trust.json")]).unwrap();let b=q.prepare(Kind::Trust,"trust.json");reject(q.service.begin(&q.owner,Kind::Trust),"SESSION_CAPACITY");q.service.cancel(&q.owner,&b.session_id).unwrap();assert!(q.service.begin(&q.owner,Kind::Trust).is_ok());}
#[test]fn production_blocks_mutations_even_with_qa_public_inputs(){let q=Qa::new();let prod=Arc::new(ImportService::new(Repository::new(q.root.clone(),Policy::production()),false));let o=prod.owner("main",123).unwrap();reject(prod.begin(&o,Kind::Package),"PRODUCTION_BOOTSTRAP_MISSING");assert!(!q.root.join("fiscal").exists());}
#[test]fn preview_stale_after_other_process_mutates_requires_new_review(){let q=Qa::new();q.trust();let s=q.prepare(Kind::Package,"package1.nomina-fiscal");let other=Repository::new(q.root.clone(),Policy::import_qa());other.accept_trust_episode(&uuid::Uuid::new_v4().to_string(),1,&[fixture("trust.json")]).unwrap();let done=q.service.confirm(&q.owner,&s.session_id,s.preview_nonce.as_ref().unwrap()).unwrap();assert_eq!(done.phase,"stale");assert_eq!(q.service.repository.open_existing().unwrap().installations,0);let old_nonce=s.preview_nonce.unwrap();let data=q.service.refresh_data(&q.owner,&s.session_id).unwrap();q.service.selected(&q.owner,&s.session_id,data).unwrap();let refreshed=q.service.get(&q.owner,&s.session_id).unwrap();assert_ne!(refreshed.preview_nonce,Some(old_nonce.clone()));reject(q.service.confirm(&q.owner,&s.session_id,&old_nonce),"PREVIEW_NONCE_MISMATCH");}
#[test]fn signed_metadata_changes_are_compared_without_running_a_calculation(){let q=Qa::new();q.trust();let a=q.prepare(Kind::Package,"package1.nomina-fiscal");q.service.confirm(&q.owner,&a.session_id,a.preview_nonce.as_ref().unwrap()).unwrap();let b=q.prepare(Kind::Package,"package2.nomina-fiscal");let details=q.service.details(&q.owner,&b.session_id,"changes",0).unwrap();assert!(details.items.iter().any(|i|i.label.contains("cash-benefits")));assert_eq!(q.service.repository.open_existing().unwrap().generation,2);}
#[test]fn native_preview_rejects_invalid_crypto_incompatible_and_future_exercise(){let q=Qa::new();q.trust();for (name,code) in [("bad-signature.nomina-fiscal","INVALID_SIGNATURE"),("unknown-key.nomina-fiscal","UNKNOWN_EDITORIAL_KEY"),("incompatible.nomina-fiscal","CONVENTION_CHANGE_REQUIRES_PROGRAM"),("package-2027.nomina-fiscal","EXERCISE_NOT_AUTHORIZED")]{let result=q.service.repository.prepare_import(&[fixture(name)],false);match result{Err(e)=>assert_eq!(e.code,code,"{name}"),Ok(_)=>panic!("Unexpected acceptance {name}")}}assert_eq!(q.service.repository.open_existing().unwrap().generation,1);}
#[test]fn signatures_do_not_override_durable_revision_conflict(){let q=Qa::new();q.trust();let a=q.prepare(Kind::Package,"package2.nomina-fiscal");q.service.confirm(&q.owner,&a.session_id,a.preview_nonce.as_ref().unwrap()).unwrap();assert_eq!(q.service.repository.prepare_import(&[fixture("package1.nomina-fiscal")],false).err().unwrap().code,"REVISION_ROLLBACK");assert_eq!(q.service.repository.prepare_import(&[fixture("conflict2.nomina-fiscal")],false).err().unwrap().code,"REVISION_CONFLICT");}
#[test]fn direct_only_is_not_inverse_available(){let q=Qa::new();q.trust();q.service.repository.accept_trust_episode(&uuid::Uuid::new_v4().to_string(),1,&[fixture("trust-direct.json")]).unwrap();let s=q.prepare(Kind::Package,"package-direct.nomina-fiscal");let p=s.summary.unwrap();assert!(p.direct);assert!(!p.inverse);assert_eq!(p.inverse_reason.as_deref(),Some("EDITORIAL_OPERATION_NOT_AUTHORIZED"));}
#[test]fn revoked_key_is_rechecked_at_confirmation(){let q=Qa::new();q.trust();let s=q.prepare(Kind::Package,"package1.nomina-fiscal");q.service.repository.accept_trust_episode(&uuid::Uuid::new_v4().to_string(),1,&[fixture("trust-revoked.json")]).unwrap();assert_eq!(q.service.confirm(&q.owner,&s.session_id,s.preview_nonce.as_ref().unwrap()).unwrap().phase,"stale");assert_eq!(q.service.repository.prepare_import(&[fixture("package1.nomina-fiscal")],false).err().unwrap().code,"KEY_REVOKED");}
#[test]fn cancelled_selection_and_no_selection_do_not_initialize(){let q=Qa::new();let s=q.service.begin(&q.owner,Kind::Package).unwrap();q.service.selector_closed();q.service.finish_error(&s.session_id,"NO_SELECTION");assert_eq!(q.service.get(&q.owner,&s.session_id).unwrap().phase,"no-selection");assert!(!q.root.join("fiscal").exists());}
#[test]fn selected_handle_copy_survives_origin_changes(){let q=Qa::new();q.trust();let path=q.root.join("original.nomina-fiscal");let bytes=fixture("package1.nomina-fiscal");fs::write(&path,&bytes).unwrap();let selected=input::read_selected(&path,2*1024*1024).unwrap();let s=q.service.begin(&q.owner,Kind::Package).unwrap();q.service.selector_closed();q.service.selected(&q.owner,&s.session_id,vec![selected]).unwrap();fs::write(&path,b"substituted invalid file").unwrap();let ready=q.service.get(&q.owner,&s.session_id).unwrap();q.service.confirm(&q.owner,&s.session_id,ready.preview_nonce.as_ref().unwrap()).unwrap();assert_eq!(q.service.repository.read_original(&nomina_fiscal_package::hashes::sha256(&bytes)).unwrap(),bytes);}
#[test]fn byte_limits_and_handle_link_policy(){let q=Qa::new();let path=q.root.join("bytes.nomina-fiscal");fs::write(&path,vec![1;2*1024*1024]).unwrap();assert_eq!(input::read_selected(&path,2*1024*1024).unwrap().len(),2*1024*1024);fs::write(&path,vec![1;2*1024*1024+1]).unwrap();reject(input::read_selected(&path,2*1024*1024),"INPUT_LIMIT");let linked=q.root.join("link.nomina-fiscal");fs::hard_link(&path,&linked).unwrap();reject(input::read_selected(&path,2*1024*1024),"REGULAR_LOCAL_FILE_REQUIRED");}
#[test]fn strict_ipc_dtos_reject_extra_authority_fields(){for field in ["path","bytes","keys","bootstrap","now","capabilities","generation","authenticated","allowDowngrade","activate"]{let value=serde_json::json!({"kind":"package",field:"forged"});assert!(serde_json::from_value::<BeginRequest>(value).is_err(),"{field}");}assert!(serde_json::from_value::<ConfirmRequest>(serde_json::json!({"sessionId":"x","previewNonce":"y","generation":1})).is_err());}
#[test]fn origin_allowlist_is_exact_not_a_frontend_claim(){for s in ["https://evil.invalid/","http://tauri.localhost.evil/","file:///C:/data","http://tauri.localhost/?mode=qa","http://user@tauri.localhost/","http://tauri.localhost/dev/history.html"]{assert!(!host_context::allowed_url(&s.parse().unwrap()),"{s}");}assert!(host_context::allowed_url(&"http://tauri.localhost/".parse().unwrap()));}
#[test]fn heavy_worker_admission_has_no_unbounded_queue(){let q=Qa::new();let work=q.service.work().unwrap();reject(q.service.work(),"BUSY");drop(work);assert!(q.service.work().is_ok());}
#[test]fn time_spent_in_selector_does_not_bypass_idle_limit(){let q=Qa::new();let s=q.service.begin(&q.owner,Kind::Trust).unwrap();q.service.age(&s.session_id,Duration::from_secs(301),Duration::from_secs(301));q.service.selector_closed();reject(q.service.selected(&q.owner,&s.session_id,vec![fixture("trust.json")]),"SESSION_EXPIRED");q.service.finish_error(&s.session_id,"SESSION_EXPIRED");assert_eq!(q.service.get(&q.owner,&s.session_id).unwrap().phase,"expired");assert!(!q.root.join("fiscal").exists());}
#[cfg(windows)]#[test]fn actual_ntfs_read_permission_is_not_a_mock(){use std::process::Command;let q=Qa::new();let file=q.root.join("denied.nomina-fiscal");fs::write(&file,fixture("package1.nomina-fiscal")).unwrap();let who=Command::new("whoami").args(["/user","/fo","csv","/nh"]).output().unwrap();let text=String::from_utf8_lossy(&who.stdout);let sid=text.trim().split(',').next_back().unwrap().trim_matches('"');assert!(sid.starts_with("S-1-"));struct Undo{path:PathBuf,sid:String}impl Drop for Undo{fn drop(&mut self){let _=Command::new("icacls").arg(&self.path).arg("/remove:d").arg(format!("*{}",self.sid)).output();}}let undo=Undo{path:file.clone(),sid:sid.into()};assert!(Command::new("icacls").arg(&file).arg("/deny").arg(format!("*{sid}:(R)")).output().unwrap().status.success());reject(input::read_selected(&file,2*1024*1024),"ACCESS_DENIED");drop(undo);assert_eq!(input::read_selected(&file,2*1024*1024).unwrap(),fixture("package1.nomina-fiscal"));}
